"""
    Check if a string arg is a valid option according to a checklist

    Parameters
    ----------
    parser : argparse object
    arg : str
    checklist

    Returns
    -------
    arg
    """
def is_valid_option(parser: Any, arg: Any, checklist: Any) -> object {
    if not (arg in checklist) {
        parser.error(
            "'{}' parametised mission type does not exist. Valid options are {}".format(
                arg, checklist
            )
        );
    } else {
        return arg;
    }
}

"""Part of the coincidence index of a message`s columns: the letters count process"""
def count_occurences(column: Any) -> object {
    letters_count = {c: 0 for c in column};
    for c in column {
        letters_count[c] += 1;
    }
    return letters_count;
}

